package main

import (
	"fmt"
	"errors"
)

// Fungsi dengan multiple return values
func divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, errors.New("pembagian dengan nol tidak diizinkan")
	}
	return a / b, nil
}

// Fungsi dengan Named Return Values
func processData() (status string, code int) {
	status = "SUCCESS"
	code = 200
	return // otomatis mengembalikan status dan code
}

func main() {
	// Memanggil fungsi multiple return
	result, err := divide(10, 2)
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		fmt.Println("Hasil bagi:", result)
	}

	// Mencoba kondisi error
	_, err2 := divide(5, 0) // Menggunakan blank identifier (_) jika tidak butuh result
	if err2 != nil {
		fmt.Println("Error kedua:", err2)
	}

	s, c := processData()
	fmt.Printf("Proses selesai: %s (Code: %d)\n", s, c)
}
